fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Precondition: n > 0 (non-empty array)

    // Only indices 0..(n/2) can have children in a 0-based array heap.
    for i in 0..(n / 2) {
        let left = 2 * i + 1;
        if left < n && a[left] < a[i] {
            return false;
        }

        let right = 2 * i + 2;
        if right < n && a[right] < a[i] {
            return false;
        }
    }

    true
}